import os
import abc
import httpx
from pydantic import BaseModel, Field, SecretStr
from typing import Optional

# Load API keys from .env file for local development
from dotenv import load_dotenv
load_dotenv()

class LLMProvider(abc.ABC):
    """Abstract Base Class for all LLM providers."""

    _client: Optional[httpx.AsyncClient] = None # To be initialized in concrete classes

    @abc.abstractmethod
    async def execute(self, prompt: str, temperature: float = 0.7) -> str:
        """Executes a prompt and returns the text response."""
        pass

    async def close(self) -> None:
        """Closes the underlying HTTP client."""
        if self._client:
            await self._client.aclose()
            self._client = None

class OpenAIProvider(LLMProvider):
    def __init__(self, api_key: SecretStr, model: str = "gpt-4o"):
        self.api_key = api_key
        self.model = model
        self.api_url = "https://api.openai.com/v1/chat/completions"
        self._client = httpx.AsyncClient() # Initialize client for reuse

    async def execute(self, prompt: str, temperature: float = 0.7) -> str:
        headers = {"Authorization": f"Bearer {self.api_key.get_secret_value()}"}
        json_data = {
            "model": self.model,
            "messages": [{"role": "user", "content": prompt}],
            "temperature": temperature,
        }
        response = await self._client.post(self.api_url, headers=headers, json=json_data, timeout=30.0)
        response.raise_for_status()
        return response.json()["choices"][0]["message"]["content"]

class GeminiProvider(LLMProvider):
    def __init__(self, api_key: SecretStr, model: str = "gemini-1.5-flash"):
        self.api_key = api_key
        self.model = model
        self.api_url = f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent"
        self._client = httpx.AsyncClient() # Initialize client for reuse

    async def execute(self, prompt: str, temperature: float = 0.7) -> str:
        params = {"key": self.api_key.get_secret_value()}
        json_data = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {"temperature": temperature},
        }
        response = await self._client.post(self.api_url, params=params, json=json_data, timeout=30.0)
        response.raise_for_status()
        return response.json()["candidates"][0]["content"]["parts"][0]["text"]

class OllamaProvider(LLMProvider):
    def __init__(self, model: str = "llama3", host: str = "http://localhost:11434"):
        self.model = model
        self.api_url = f"{host}/api/generate"
        self._client = httpx.AsyncClient() # Initialize client for reuse

    async def execute(self, prompt: str, temperature: float = 0.7) -> str:
        json_data = {
            "model": self.model,
            "prompt": prompt,
            "stream": False,
            "options": {"temperature": temperature},
        }
        response = await self._client.post(self.api_url, json=json_data, timeout=60.0)
        response.raise_for_status()
        return response.json()["response"]

class ProviderFactory:
    """Factory to create provider instances from configuration."""
    _providers = {
        "openai": OpenAIProvider,
        "gemini": GeminiProvider,
        "ollama": OllamaProvider,
    }

    @staticmethod
    def create(provider_name: str, config: dict) -> LLMProvider:
        provider_class = ProviderFactory._providers.get(provider_name.lower())
        if not provider_class:
            raise ValueError(f"Unknown provider: {provider_name}")

        # API keys are expected to be SecretStr for security
        api_key = config.pop("api_key", None)
        if api_key:
            config["api_key"] = SecretStr(api_key)

        return provider_class(**config)
